-- Vendor Contacts directory.
--
-- A shared, org-wide directory of vendor / distributor / manufacturer's-rep
-- contacts, surfaced in the app under the "Directory" sidebar entry. Replaces
-- the old standalone HTML page that persisted to localStorage and gated
-- additions behind a mailto approval queue.
--
-- Access model: ANY authenticated user can add, edit, deactivate, and delete
-- any contact. There is no admin gate and no approval step — it's a shared
-- place to dump and maintain vendor contact info. "Deactivate" flips `active`
-- (soft hide); delete removes the row permanently.
--
-- Logos are fetched client-side from the contact's website domain (Clearbit /
-- favicon), so nothing logo-related is stored here.

create table if not exists public.vendor_contacts (
  id            uuid primary key default gen_random_uuid(),
  company       text not null,
  company_type  text check (company_type in ('manufacturer','distributor','rep','other')),
  rep_for       text not null default '',          -- comma-separated brands (reps/distributors)
  name          text not null default '',
  title         text not null default '',
  email         text not null default '',
  phone         text not null default '',
  website       text not null default '',
  role          text not null default '',          -- "what they do for us"
  notes         text not null default '',
  technical     boolean not null default false,
  active        boolean not null default true,      -- deactivate = soft hide; delete = hard remove
  created_by    uuid references public.profiles(id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);

alter table public.vendor_contacts enable row level security;

-- Everyone-can-do-everything (authenticated only). Mirrors the open access
-- model the feature calls for; auth.uid() is non-null only for signed-in users.
create policy "Authenticated can read vendor contacts"
  on public.vendor_contacts for select
  using (auth.uid() is not null);

create policy "Authenticated can insert vendor contacts"
  on public.vendor_contacts for insert
  with check (auth.uid() is not null);

create policy "Authenticated can update vendor contacts"
  on public.vendor_contacts for update
  using (auth.uid() is not null)
  with check (auth.uid() is not null);

create policy "Authenticated can delete vendor contacts"
  on public.vendor_contacts for delete
  using (auth.uid() is not null);

create index if not exists idx_vendor_contacts_company on public.vendor_contacts (company);
create index if not exists idx_vendor_contacts_active  on public.vendor_contacts (active);

-- Seed the existing ~80 contacts, but only into an empty table so re-running
-- the migration never duplicates rows.
do $$
begin
  if not exists (select 1 from public.vendor_contacts) then
    ;
  end if;
end $$;
